import click
from click.testing import CliRunner

runner = CliRunner()

def show(name, cmd, args=(), env=None):
    r = runner.invoke(cmd, list(args), env=env or {}, standalone_mode=False)
    print(f"{name:60s} -> return={r.return_value!r} exc={type(r.exception).__name__ if r.exception else None} out={r.output!r}")

# 1. bool flag with envvar
@click.command()
@click.option("--flag", is_flag=True, envvar="X")
def c1(flag):
    return flag
show("bool flag env X=1", c1, env={"X": "1"})
show("bool flag env X=0", c1, env={"X": "0"})
show("bool flag env X=true", c1, env={"X": "true"})
show("bool flag no env", c1)

# 2. non-bool flag with flag_value + envvar
@click.command()
@click.option("--flag", "arg", is_flag=True, flag_value="flag", envvar="X")
def c2(arg):
    return arg
show("flag_value='flag' env X=flag", c2, env={"X": "flag"})
show("flag_value='flag' env X=1", c2, env={"X": "1"})
show("flag_value='flag' no env", c2)
show("flag_value='flag' cmdline", c2, args=["--flag"])

# 3. flag_value=False with envvar
@click.command()
@click.option("--flag", "arg", is_flag=True, flag_value=False, envvar="X")
def c3(arg):
    return arg
show("flag_value=False env X=1", c3, env={"X": "1"})
show("flag_value=False env X=0", c3, env={"X": "0"})
show("flag_value=False no env", c3)
show("flag_value=False cmdline", c3, args=["--flag"])

# 4. argument with envvar (plain)
@click.command()
@click.argument("arg", envvar="X")
def c4(arg):
    return arg
show("argument env X=hello", c4, env={"X": "hello"})

# 5. option with default True and flag_value False, envvar
